// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and init
        vm.prank(address(0x1));
        c.init(address(0x2), address(0x3), address(0x4));

        // First newGrantProposal: proposalCount becomes 1 (reference) or 2 (bug)
        c.newGrantProposal(address(0xa), 100);

        // Second newGrantProposal: reference proposalCount=2, bug proposalCount=4
        c.newGrantProposal(address(0xb), 200);

        // Record the proposalCount after two calls
        uint256 countBefore = c.proposalCount();

        // Third newGrantProposal: reference proposalCount=3, bug proposalCount=6
        c.newGrantProposal(address(0xc), 300);

        // Now cancelProposal(oldProposalID=2, newProposalID=3)
        // For reference: oldProposalID=2 (mapPID_finalising[2] is false) => require(mapPID_finalising[oldProposalID]) will revert
        // We must first finalise proposal 2 to make it finalising true.
        // To do that, we need a quorum and a majority for a non-DAO/UTILS/REWARD type (GRANT).
        // For simplicity, we directly call _finalise via voteProposal with enough votes:
        // But we cannot manipulate vault, so we simulate intermediate state:
        // Actually, the difference manifests directly: after cancelProposal, proposalCount differs because
        // the proposalCount increment affects mapPID_grant index mapping.
        // Since cancelProposal does not modify proposalCount, the divergence must come from before.
        // Let's just assert after two calls (reference count=2, bug count=4).
        // That already shows divergence.

        // Assert that proposalCount equals 2 (the correct behavior after two calls)
        assertTrue(c.proposalCount() == 2, "proposalCount should be 2 after two newGrantProposal calls");
    }
}

